def split_csv(line):
    """Split one CSV line into fields.

    Fields may be wrapped in double quotes.  Inside quotes a comma is a
    literal character and a doubled quote ("") represents one quote
    character.  The surrounding quotes are not part of the field value.
    """
    fields = []
    current = []
    in_quotes = False
    i = 0
    length = len(line)

    while i < length:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < length and line[i + 1] == '"':
                    current.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                current.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(current))
                current = []
            elif ch == '"':
                in_quotes = True
            else:
                current.append(ch)
        i += 1

    fields.append(''.join(current))
    return fields
